questions.q:
다음 C 프로그램을 실행하면서 사용자가 1, 2, 3, 4를 차례대로 입력했을 때, 출력 결과는?

#include <stdio.h>

int main()
{
   int ary[4];
   int sum = 0;
   int i;

   for (i = 0; i < 4; i++) {
     printf("%d번 째 값을 입력하시오 : ", i + 1);
     scanf("%d", &ary[i]);
   }

   for (i = 3; i > 0; i--)
     sum += ary[i];

   printf("%d \n", sum);
   return 0;
}

다음 C 프로그램의 실행 결과로 옳은 것은?

#include <stdio.h>

int star = 10;

void printStar() {
   printf("%d \n", star);
}

int main()
{
   int star = 5;

   printStar();
   printf("%d \n", star);
   return 0;
}
